PLANTES = [
L("Chapitre II : La fleur et la formation des gamètes chez les Spermaphytes", [89, 97],
  ["Décrire l’organisation d’une fleur.", "Décrire l’anthère et la formation du grain de pollen.", "Décrire l’ovule et la formation du sac embryonnaire."],
  "Où se forment les gamètes d’une plante à fleurs ?",
  "Les fleurs peuvent être monosexuées (mâles ou femelles, comme chez le palmier dattier) ou bisexuées. Une fleur complète comprend, insérés sur le réceptacle, de l’extérieur vers l’intérieur : le calice (sépales) et la corolle (pétales), qui forment le périanthe protecteur ; l’androcée, ensemble des étamines (filet + anthère où se forme le pollen) ; le gynécée ou pistil, ensemble des carpelles (stigmate, style, ovaire contenant les ovules). L’anthère jeune montre quatre sacs polliniques avec l’assise mécanique, les assises nourricières et les cellules-mères du pollen ; dans l’anthère mûre le pollen est formé et l’assise mécanique est prête à s’ouvrir (déhiscence). Microsporogenèse : chaque cellule-mère (2n) subit une méiose et donne une tétrade de quatre microspores (n) ; chaque microspore subit une mitose et donne le grain de pollen, gamétophyte mâle, formé d’une cellule végétative et d’une cellule reproductrice qui se divisera en deux gamètes mâles ; il est entouré de l’intine et de l’exine percée de pores. L’ovule (funicule, hile, chalaze, deux téguments, micropyle, nucelle) peut être droit, recourbé ou renversé (le plus répandu). Macrosporogenèse : la cellule-mère du sac embryonnaire subit une méiose ; trois macrospores dégénèrent ; la macrospore restante subit trois mitoses (8 noyaux) et donne le sac embryonnaire à 7 cellules (oosphère et deux synergides au micropyle, trois antipodes, cellule centrale à deux noyaux polaires) : c’est le gamétophyte femelle.",
  ["Fleur : calice, corolle, androcée, gynécée.", "Étamine = filet + anthère ; carpelle = stigmate + style + ovaire.", "Pollen : méiose puis mitose (gamétophyte mâle).", "Sac embryonnaire : méiose puis 3 mitoses (8 noyaux, 7 cellules).", "Oosphère = gamète femelle."],
  ("Combien de grains de pollen donne une cellule-mère du pollen ?", "Quatre : la méiose donne une tétrade de quatre microspores, chacune devenant un grain de pollen."),
  [S("Organisation de la fleur", table=[["Verticille", "Pièces", "Rôle"], ["Calice", "sépales", "protection"], ["Corolle", "pétales", "protection, attraction"], ["Androcée", "étamines (filet, anthère)", "pollen"], ["Gynécée (pistil)", "carpelles (stigmate, style, ovaire)", "ovules"]]),
   S("Formation des gamétophytes", table=[["", "Mâle", "Femelle"], ["Lieu", "sac pollinique", "nucelle de l’ovule"], ["Méiose", "4 microspores fertiles", "1 macrospore fertile sur 4"], ["Mitoses", "1 (+1 pour les gamètes)", "3"], ["Gamétophyte", "grain de pollen", "sac embryonnaire"]]),
   S("Remarque", ["(Correction : le manuel écrit « le carpelle est formé de trois parties : le style, l’ovaire, l’ovule et le stigmate » ; les trois parties sont le stigmate, le style et l’ovaire, qui contient les ovules.)"])],
  apps=[("Qu’est-ce qu’une plante dioïque ?", "Une plante dont les fleurs mâles et les fleurs femelles sont portées par des pieds différents (palmier dattier)."), ("Quel type d’ovule est le plus répandu ?", "L’ovule renversé (anatrope), avec un raphé.")]),
L("Chapitre II : Pollinisation, double fécondation et formation de la graine", [98, 102],
  ["Distinguer autopollinisation et pollinisation croisée.", "Décrire la germination du pollen et la croissance du tube pollinique.", "Expliquer la double fécondation et la formation de la graine et du fruit."],
  "Pourquoi parle-t-on de « double » fécondation chez les plantes à fleurs ?",
  "La pollinisation est le transport du pollen d’une anthère jusqu’au stigmate. Elle est directe (autogamie) sur la même fleur hermaphrodite, ou croisée (allogamie) quand le pollen vient d’une autre fleur, obligatoire pour les fleurs unisexuées (plante monoïque ou dioïque) ; le vent et les insectes transportent le pollen. Sur le stigmate, le grain de pollen se réhydrate et germe : l’intine sort par un pore et forme le tube pollinique, dirigé par le noyau végétatif, qui progresse dans le style jusqu’au micropyle de l’ovule. Le tube pénètre entre l’oosphère et une synergide et libère deux gamètes mâles. L’un féconde l’oosphère et donne l’œuf principal (2n), à l’origine de l’embryon ; l’autre s’unit aux deux noyaux polaires et donne l’œuf accessoire triploïde (3n), à l’origine de l’albumen, tissu de réserves. Les synergides et les antipodes dégénèrent. L’ovule devient la graine (embryon avec radicule, tigelle, gemmule et un ou deux cotylédons ; albumen ; téguments durcis) et la paroi de l’ovaire devient le fruit ; sépales, pétales et étamines se fanent.",
  ["Autogamie et allogamie.", "Tube pollinique jusqu’au micropyle.", "Gamète 1 + oosphère → œuf principal 2n → embryon.", "Gamète 2 + 2 noyaux polaires → œuf accessoire 3n → albumen.", "Ovule → graine ; ovaire → fruit."],
  ("Un noyau polaire possède 10 chromosomes. Combien en possède l’albumen ?", "3n = 30 chromosomes (2 noyaux polaires n + 1 gamète mâle n)."),
  [S("Double fécondation", table=[["Union", "Produit", "Devenir"], ["gamète mâle + oosphère (n + n)", "œuf principal (2n)", "embryon"], ["gamète mâle + 2 noyaux polaires (n + 2n)", "œuf accessoire (3n)", "albumen"]]),
   S("Transformations après fécondation", ["Ovule → graine ; téguments → enveloppes de la graine.", "Paroi de l’ovaire → fruit.", "Synergides, antipodes, noyau végétatif → dégénèrent."])],
  apps=[("Pourquoi la pollinisation est-elle obligatoirement croisée chez le palmier dattier ?", "Parce que ses fleurs sont unisexuées et portées par des pieds différents."), ("Quel est le rôle du noyau végétatif ?", "Il dirige la croissance du tube pollinique.")]),
L("Chapitre II : Germination de la graine et cycle de développement", [103, 107],
  ["Déterminer expérimentalement les conditions de la germination.", "Décrire les étapes de la germination épigée et hypogée.", "Décrire le cycle de développement et le cycle chromosomique d’une angiosperme."],
  "De quoi une graine a-t-elle besoin pour germer ?",
  "On fait germer des graines (haricot, maïs, lentille) en ne faisant varier qu’un facteur : seules les graines arrosées germent ; à humidité convenable, seules celles placées à environ 20 °C germent ; elles germent aussi à l’obscurité. Il faut donc de l’eau, une température convenable et de l’oxygène, et un état physiologique favorable (levée de la dormance, parfois par le froid). Une graine de pois placée sur du coton humide augmente de masse en deux phases : l’imbibition, rapide et réversible, puis, après la sortie de la radicule, la croissance, irréversible. La germination est la reprise du développement de l’embryon aux dépens des réserves : la graine passe de la vie ralentie à la vie active ; la plantule devient autonome quand ses racines absorbent l’eau et les ions et que ses feuilles font la photosynthèse. La germination est épigée si les cotylédons sortent du sol (l’hypocotyle s’allonge, haricot) et hypogée s’ils restent dans le sol (hypocotyle court). Le cycle de développement fait alterner le sporophyte (2n), plante feuillée qui porte les fleurs, et les gamétophytes (n), grain de pollen et sac embryonnaire, très réduits. La méiose a lieu dans les sacs polliniques et les ovules, la fécondation rétablit la diploïdie : le cycle est haplo-diplophasique, à diplophase dominante.",
  ["Conditions : eau, température, oxygène, levée de dormance.", "Imbibition réversible, croissance irréversible.", "Germination épigée / hypogée.", "Sporophyte 2n dominant ; gamétophytes n réduits.", "Cycle haplo-diplophasique."],
  ("Dans une expérience, des graines placées à 20 °C sur du coton sec ne germent pas. Quel facteur manque ?", "L’eau : sans humidité, l’imbibition et la reprise de la vie active sont impossibles."),
  [S("Expériences", table=[["Condition", "Résultat", "Conclusion"], ["Sans arrosage", "pas de germination", "l’eau est nécessaire"], ["Froid (coton humide)", "pas de germination", "température convenable nécessaire"], ["Obscurité", "germination", "la lumière n’est pas indispensable"]]),
   S("Cycle chromosomique", ["Sporophyte (2n) → méiose → microspores et macrospore (n) → grain de pollen et sac embryonnaire (n) → double fécondation → œuf (2n) → graine → nouveau sporophyte."])],
  apps=[("Quelle différence entre germination épigée et hypogée ?", "Épigée : les cotylédons sortent du sol ; hypogée : ils restent dans le sol."), ("Quel est le gamétophyte femelle d’une angiosperme ?", "Le sac embryonnaire.")]),
]

COEUR = [
L("Chapitre V : L’activité cardiaque et son automatisme", [252, 262],
  ["Comparer le cœur humain et le cœur de grenouille ; décrire le myocarde.", "Interpréter un cardiogramme et un électrocardiogramme.", "Démontrer l’automatisme cardiaque et localiser le tissu nodal."],
  "Pourquoi un cœur isolé continue-t-il à battre ?",
  "Le cœur humain, entouré du péricarde, a quatre cavités (deux oreillettes, deux ventricules) ; le ventricule gauche a la paroi la plus épaisse. Le cœur de grenouille a deux oreillettes, un seul ventricule, un sinus veineux et un bulbe artériel, sans vaisseaux coronaires. Le myocarde est formé de cellules musculaires striées à un noyau central, reliées entre elles. Chez la grenouille, les contractions se succèdent dans l’ordre sinus → oreillettes → ventricule → bulbe. Le cardiogramme comprend un ressaut (systole auriculaire), une partie ascendante (début de la systole ventriculaire, contraction isométrique), un palier (éjection, contraction isotonique) et une partie descendante (diastole générale). L’électrocardiogramme montre les ondes P (dépolarisation auriculaire), QRS (ventriculaire) et T. La fréquence cardiaque d’un adulte au repos est de 50 à 80 battements par minute ; le volume d’éjection systolique de 70 mL au repos à 150 mL à l’effort ; débit cardiaque = VES × FC. Un cœur de grenouille dont les centres nerveux sont détruits, ou isolé dans du liquide de Ringer, continue à battre : c’est l’automatisme cardiaque. Les ligatures de Stannius montrent que le centre principal est le sinus veineux, et qu’un centre secondaire plus lent existe à la jonction oreillettes-ventricule. Chez les Mammifères, l’automatisme est dû au tissu nodal : nœud sinusal (rythme imposé), nœud septal (auriculo-ventriculaire), faisceau de His et réseau de Purkinje ; la section du faisceau de His dissocie le rythme des oreillettes et des ventricules (rythme idio-ventriculaire lent).",
  ["Cœur humain 4 cavités ; grenouille : 1 ventricule.", "Cardiogramme : ressaut, montée, palier, descente.", "DC = VES × FC.", "Automatisme : le cœur isolé bat.", "Tissu nodal : nœud sinusal → nœud septal → His → Purkinje."],
  ("FC = 70 battements/min et VES = 70 mL. Débit cardiaque ?", "DC = 70 × 70 = 4 900 mL/min, environ 5 L/min."),
  [S("Ligatures de Stannius (grenouille)", table=[["Ligature", "Résultat", "Conclusion"], ["Sinus / oreillettes", "le sinus bat, le reste s’arrête puis reprend lentement", "le sinus est le centre principal"], ["Oreillettes / ventricule", "le ventricule reprend un rythme propre lent", "centre secondaire à la jonction"]]),
   S("Hiérarchie des centres (Homme)", table=[["Centre", "Rythme propre (battements/min)"], ["Nœud sinusal", "120 à 130 (cœur énervé)"], ["Nœud septal", "40 à 60"], ["Ventricules (idio-ventriculaire)", "25 à 35"]]),
   S("Remarque", ["(Correction : chez l’Homme, le palier correspond à l’éjection du sang dans l’aorte et l’artère pulmonaire ; le manuel écrit « dans le bulbe », qui n’existe que chez la grenouille.)", "(Correction : la précharge est le degré d’étirement du myocarde en fin de diastole, et non « en fin de systole ».)"])],
  apps=[("Que se passe-t-il chez l’Homme si le faisceau de His est altéré (maladie de Stokes-Adams) ?", "Les ventricules battent à leur propre rythme lent, indépendamment des oreillettes."), ("Quelle cavité a la paroi la plus épaisse ?", "Le ventricule gauche, qui envoie le sang dans tout le corps.")]),
L("Chapitre V : Adaptation de l’activité cardiaque (innervation et hormones)", [262, 266],
  ["Décrire la double innervation du cœur.", "Expliquer le rôle des barorécepteurs et des chémorécepteurs.", "Comparer les effets du sympathique, du parasympathique et de l’adrénaline."],
  "Comment le cœur accélère-t-il pendant un effort ?",
  "Le cœur reçoit une double innervation du système végétatif. Le centre parasympathique bulbaire (cardiomodérateur), situé dans le bulbe rachidien, agit par les nerfs pneumogastriques (nerfs X) : leur stimulation ralentit le cœur (bradycardie), leur section l’accélère. Le centre sympathique médullaire (cardioaccélérateur) agit par les nerfs sympathiques cardiaques : leur stimulation accélère et renforce les contractions (tachycardie). Les barorécepteurs de la crosse aortique et des sinus carotidiens, sensibles à l’étirement de la paroi, envoient des messages aux centres par les nerfs de Cyon-Ludwig et de Héring. Les chémorécepteurs sont sensibles au CO₂ et aux métabolites acides produits pendant l’effort. Les nerfs agissent par des médiateurs chimiques (expérience de Loewi) : acétylcholine pour le parasympathique, noradrénaline pour le sympathique. L’adrénaline de la médullosurrénale, libérée lors d’une émotion ou d’un stress, accélère le cœur (régulation hormonale cardioaccélératrice). À tout instant, le rythme est la résultante de ces systèmes ; le système nerveux central les module (une émotion violente l’accélère).",
  ["Parasympathique (nerf X) : cardiomodérateur.", "Sympathique : cardioaccélérateur.", "Barorécepteurs : crosse aortique, sinus carotidiens.", "Médiateurs : acétylcholine, noradrénaline.", "Adrénaline : accélération hormonale."],
  ("Chez un animal, la section des deux nerfs X accélère le cœur. Que peut-on conclure ?", "Les nerfs X exercent en permanence un freinage sur le cœur (tonus cardiomodérateur)."),
  [S("Systèmes régulateurs", table=[["Système", "Récepteurs", "Voie sensitive", "Centre", "Voie motrice", "Effet"], ["Parasympathique", "sinus carotidien, crosse aortique", "nerfs de Héring et de Cyon", "bulbaire", "nerf X", "bradycardie"], ["Orthosympathique", "—", "—", "médullaire", "nerfs cardiaques", "tachycardie"], ["Hormonal", "—", "—", "médullosurrénale", "adrénaline (sang)", "tachycardie"]]),
   S("Expérience de Loewi", ["Le liquide d’un cœur dont on stimule le nerf X ralentit un second cœur : le nerf agit par une substance chimique, l’acétylcholine."])],
  apps=[("Quels nerfs portent les messages des barorécepteurs ?", "Les nerfs de Héring (sinus carotidiens) et de Cyon (crosse aortique)."), ("Pourquoi une émotion violente accélère-t-elle le cœur ?", "Elle provoque une décharge d’adrénaline par la médullosurrénale.")]),
L("Chapitre V : La pression artérielle et sa régulation nerveuse", [266, 275],
  ["Définir la pression artérielle et la mesurer.", "Citer ses facteurs de variation.", "Expliquer la correction réflexe d’une hypertension et d’une hypotension."],
  "Que fait l’organisme quand la pression artérielle baisse après une hémorragie ?",
  "La pression artérielle (PA) est la force exercée par le sang sur la paroi des artères ; elle dépend du débit cardiaque et de la résistance des vaisseaux (PA = DC × R) et de la volémie. Elle oscille entre la pression systolique (maximale, contraction du ventricule gauche) et la pression diastolique (minimale). Elle se mesure directement par un cathéter relié à un manomètre, ou indirectement avec un sphygmomanomètre et un stéthoscope sur l’artère brachiale. Elle varie avec l’effort, le sommeil, le stress, la position, l’excès de sel, les hémorragies, mais les perturbations sont vite corrigées. La stimulation du bulbe provoque une bradycardie et une hypotension ; la stimulation de la moelle une tachycardie, une hypertension et une vasoconstriction. Une ligature des carotides sous le sinus (hypotension sinusale) accélère le cœur et augmente la PA ; une hypertension du sinus ralentit le cœur et abaisse la PA. Correction d’une hypertension : l’étirement des barorécepteurs augmente la fréquence des PA dans les nerfs de Héring et de Cyon ; le centre bulbaire stimule le nerf X et inhibe le centre sympathique (par un neurone inhibiteur) : bradycardie et vasodilatation ramènent la PA à la normale. Correction d’une hypotension : la baisse de stimulation des barorécepteurs lève l’inhibition du centre vasomoteur et diminue l’activité du nerf X : tachycardie et vasoconstriction. C’est une boucle réflexe : capteurs, centre intégrateur, effecteurs.",
  ["PA = DC × R ; systolique et diastolique.", "Mesure au sphygmomanomètre.", "Barorécepteurs → nerfs de Héring et de Cyon → bulbe.", "Hypertension → nerf X activé, sympathique inhibé.", "Hypotension → tachycardie + vasoconstriction."],
  ("Après une petite hémorragie, la fréquence cardiaque augmente. Expliquer.", "La PA baisse ; les barorécepteurs sont moins étirés, le nerf X est moins actif et le sympathique est levé d’inhibition : tachycardie et vasoconstriction."),
  [S("Expériences", table=[["Expérience", "Résultat", "Conclusion"], ["Ligature des carotides sous le sinus", "tachycardie, PA ↑", "la baisse de pression sinusale déclenche une hausse"], ["Pression augmentée dans le sinus", "bradycardie, PA ↓", "le sinus contient des barorécepteurs"], ["Stimulation du bulbe", "bradycardie, hypotension", "centre cardiomodérateur"], ["Stimulation de la moelle", "tachycardie, hypertension", "centre accélérateur et vasoconstricteur"]]),
   S("Boucle réflexe", ["Capteurs : barorécepteurs.", "Voies afférentes : nerfs de Héring et de Cyon.", "Centre : bulbe rachidien.", "Voies efférentes : nerf X, nerfs sympathiques.", "Effecteurs : cœur, vaisseaux."])],
  apps=[("Que représente une PA de 12/8 ?", "Pression systolique de 12 cm Hg (120 mm Hg) et diastolique de 8 cm Hg (80 mm Hg)."), ("Quel est l’effet de l’anesthésie de la zone dorsale du bulbe ?", "Une tachycardie et une augmentation de la PA (le frein disparaît).")]),
L("Chapitre V : Régulation hormonale de la pression artérielle", [276, 280],
  ["Exploiter des données sur les corticosurrénales et les reins.", "Expliquer le système rénine-angiotensine-aldostérone.", "Citer le rôle de l’adrénaline et de l’ADH."],
  "Pourquoi l’obstruction d’une artère rénale provoque-t-elle une hypertension ?",
  "Une tumeur des corticosurrénales provoque une forte hypertension par accumulation de Na⁺. Chez un malade dont l’artère rénale gauche est obstruée, la veine du rein gauche contient beaucoup plus de rénine (12 contre 6) : un rein mal irrigué sécrète de la rénine. La rénine transforme l’angiotensinogène, produit par le foie, en angiotensine ; celle-ci est vasoconstrictrice, stimule les centres cardioaccélérateur et vasoconstricteur, diminue la filtration glomérulaire et stimule la sécrétion d’aldostérone par les corticosurrénales ; l’aldostérone augmente la réabsorption du Na⁺ par le rein, diminue la diurèse et augmente la volémie, donc la PA. La régulation hormonale agit à long terme, après la régulation nerveuse, en cas d’hypotension ; elle agit sur le tonus des vaisseaux et sur la volémie. L’adrénaline et la noradrénaline de la médullosurrénale accélèrent le cœur et resserrent les artérioles : régulation à court terme. L’ADH (vasopressine), produite par l’hypothalamus et libérée par la posthypophyse quand les volorécepteurs signalent une baisse du volume sanguin, réduit la perte d’eau par le rein et resserre les vaisseaux.",
  ["Rein mal irrigué → rénine ↑.", "Rénine : angiotensinogène → angiotensine.", "Angiotensine : vasoconstriction + aldostérone.", "Aldostérone : réabsorption de Na⁺ → volémie ↑.", "Adrénaline (court terme), ADH (eau)."],
  ("Pourquoi la rénine est-elle plus abondante dans la veine du rein gauche du malade ?", "Le rein gauche, dont l’artère est obstruée, reçoit peu de sang et sécrète beaucoup de rénine."),
  [S("Données du malade (rénine, unités arbitraires)", table=[["", "Rein droit", "Rein gauche (artère obstruée)", "Rein normal"], ["Artère", "6", "6", "4"], ["Veine", "6", "12", "5"]]),
   S("Système rénine-angiotensine-aldostérone", ["Baisse de la PA rénale → rein → rénine.", "Angiotensinogène (foie) → angiotensine.", "Angiotensine → vasoconstriction + corticosurrénale → aldostérone.", "Aldostérone → réabsorption de Na⁺ et d’eau → volémie ↑ → PA ↑."]),
   S("Autres hormones", ["Adrénaline : accélération cardiaque, vasoconstriction (court terme).", "ADH : diurèse ↓, vasoconstriction."])],
  apps=[("Quelle glande sécrète l’aldostérone ?", "La corticosurrénale."), ("Pourquoi l’ADH est-elle dite hypertensive ?", "Elle réduit l’élimination d’eau par le rein (volémie ↑) et resserre les vaisseaux.")]),
]

IMMUNO = [
L("Chapitre VI : La réponse immunitaire spécifique — antigènes et anticorps", [294, 300],
  ["Exploiter des expériences (anatoxine tétanique, BCG) pour distinguer immunité humorale et cellulaire.", "Définir antigène, déterminant antigénique et anticorps.", "Décrire la structure des anticorps et leurs classes."],
  "Comment un vaccin protège-t-il contre une maladie ?",
  "Une souris témoin meurt après injection de toxine tétanique ; une souris vaccinée par l’anatoxine survit ; le sérum d’une souris vaccinée protège une souris neuve : c’est la réponse immunitaire à médiation humorale (RIMH), transférable par le sérum (anticorps). Chez le cobaye, l’immunité contre le bacille de Koch, obtenue par le BCG, se transfère par les lymphocytes et non par le sérum : c’est la réponse immunitaire à médiation cellulaire (RIMC). L’immunité spécifique est spécifique d’un antigène, acquise, transférable et dotée de mémoire. La RIMH, contre les agresseurs extracellulaires (bactéries, toxines), fait intervenir les lymphocytes B ; la RIMC, contre les cellules infectées et cancéreuses, les lymphocytes T. Un antigène est une substance reconnue comme étrangère ; la partie reconnue est le déterminant antigénique ou épitope, dont le nombre fixe la valence. Un anticorps (immunoglobuline) est une protéine en forme de Y formée de deux chaînes lourdes et deux chaînes légères liées par des ponts disulfure ; ses régions variables forment deux sites de liaison complémentaires de l’épitope ; la région constante permet la liaison aux phagocytes et au complément. Il existe cinq classes : IgG (75 %, seule à traverser le placenta), IgA (sécrétions), IgM, IgD et IgE.",
  ["RIMH : transférable par le sérum (anticorps).", "RIMC : transférable par les lymphocytes T.", "Spécificité, mémoire, transférabilité.", "Épitope = déterminant antigénique.", "Anticorps : 2 chaînes lourdes + 2 légères, forme en Y."],
  ("Un sérum prélevé sur une souris vaccinée contre le tétanos protège-t-il contre la diphtérie ?", "Non : les anticorps sont spécifiques de l’antigène qui a provoqué leur production."),
  [S("Deux types de réponse", table=[["", "RIMH", "RIMC"], ["Agresseur", "extracellulaire (bactérie, toxine)", "cellule infectée, cancéreuse, greffon"], ["Cellules", "lymphocytes B → plasmocytes", "lymphocytes T8 → LTc"], ["Effecteurs", "anticorps circulants", "lymphocytes cytotoxiques"], ["Transfert", "par le sérum", "par les lymphocytes"]]),
   S("Structure d’un anticorps", ["2 chaînes lourdes + 2 chaînes légères, ponts disulfure, charnière.", "Régions variables (côté NH₂) : 2 sites de fixation de l’antigène.", "Région constante : fixation aux phagocytes, activation du complément."])],
  apps=[("Quelle classe d’anticorps passe de la mère au fœtus ?", "Les IgG."), ("Qu’est-ce que la valence d’un antigène ?", "Le nombre de déterminants antigéniques qu’il porte.")]),
L("Chapitre VI : Déroulement de la réponse immunitaire et mémoire", [301, 306],
  ["Décrire les phases d’induction, d’amplification-différenciation et effectrice.", "Expliquer la coopération cellulaire et le rôle des interleukines.", "Comparer réponses primaire et secondaire."],
  "Pourquoi un rappel de vaccin donne-t-il une réponse plus rapide et plus forte ?",
  "Quand un élément étranger franchit la peau et les muqueuses, la réaction inflammatoire non spécifique se produit d’abord, puis la réponse spécifique en trois phases. Induction : les cellules présentatrices de l’antigène (macrophages, cellules dendritiques) captent l’antigène et migrent vers les ganglions ; les LB reconnaissent directement l’antigène, les LT4 le reconnaissent associé au CMH II et les LT8 associé au CMH I (double reconnaissance) ; la coopération cellulaire se fait par contact et par les interleukines (IL1, IL2). Amplification et différenciation : les lymphocytes sélectionnés et activés par l’IL2 des LT4 se multiplient (clones) ; les LB deviennent des plasmocytes (beaucoup de REG et d’appareil de Golgi) qui sécrètent des anticorps ; les LT4 deviennent des LT auxiliaires ; les LT8 deviennent des LT cytotoxiques (perforines). Phase effectrice : les anticorps forment des complexes immuns qui neutralisent l’antigène, activent le complément (lyse) et favorisent la phagocytose (opsonisation) ; les LTc se fixent sur les cellules infectées et libèrent des perforines qui forment des pores et font éclater la cellule. La mémoire repose sur les LB et LT mémoires à longue durée de vie : la réponse primaire est tardive, faible et brève ; la réponse secondaire est rapide, intense, durable et plus affine (surtout des IgG).",
  ["Induction : CPA, reconnaissance, coopération (IL).", "Amplification : clones ; LB → plasmocytes.", "Effectrice : complexes immuns, complément, opsonisation.", "LTc : perforines.", "Mémoire : réponse secondaire rapide et forte."],
  ("Pourquoi une souris sans thymus produit-elle peu d’anticorps contre la plupart des antigènes ?", "Sans LT4, il n’y a pas d’interleukine 2 pour activer et multiplier les LB : la coopération cellulaire est impossible."),
  [S("Les trois phases", table=[["Phase", "Événements"], ["Induction", "présentation par les CPA ; reconnaissance par LB, LT4 (CMH II), LT8 (CMH I)"], ["Amplification-différenciation", "multiplication clonale ; plasmocytes, LTa, LTc, cellules mémoires"], ["Effectrice", "anticorps (neutralisation, complément, opsonisation) ; LTc (perforines)"]]),
   S("Réponses primaire et secondaire", table=[["", "Primaire", "Secondaire"], ["Délai", "long", "court"], ["Intensité", "faible", "forte"], ["Durée", "brève", "longue"], ["Anticorps", "surtout IgM", "surtout IgG, plus affins"]])],
  apps=[("Quelle molécule permet au LTc de détruire une cellule infectée ?", "La perforine, qui forme un canal dans sa membrane."), ("Qu’est-ce que l’opsonisation ?", "La fixation des complexes immuns sur les phagocytes par la région constante des anticorps, ce qui facilite la phagocytose.")]),
L("Chapitre VI : Dysfonctionnements du système immunitaire", [307, 313],
  ["Expliquer l’allergie (hypersensibilité immédiate).", "Définir une maladie auto-immune et en citer des exemples.", "Décrire le VIH, son cycle et les phases de l’infection ; distinguer déficits congénitaux et acquis."],
  "Comment un virus peut-il détruire le système immunitaire lui-même ?",
  "Le système immunitaire peut réagir de façon excessive ou insuffisante. L’allergie est une réaction excessive à un allergène (pollen, poussières, acariens, aliments, médicaments, venins…) : lors du premier contact, des IgE se fixent sur les mastocytes ; au contact suivant, l’allergène relie les IgE et les mastocytes libèrent de l’histamine (urticaire, asthme, rhume, œdème). Il existe une allergie humorale (hypersensibilité immédiate) et une allergie cellulaire (retardée). Une maladie auto-immune survient quand le système immunitaire ne tolère plus le soi et détruit ses propres cellules (auto-anticorps) : diabète insulino-dépendant (cellules β du pancréas), sclérose en plaques (myéline), myasthénie (synapse neuromusculaire), anémie pernicieuse, polyarthrite rhumatoïde. Les déficits congénitaux apparaissent après 6 mois, quand les anticorps maternels disparaissent (absence de LB, de thymus ou de cellules souches : enfants conservés dans des « bulles » stériles). Le VIH, rétrovirus à ARN avec transcriptase inverse, intégrase et protéase, entouré d’une enveloppe portant la gp120, se fixe sur la protéine CD4 des LT4 et des macrophages ; son ARN est rétrotranscrit en ADN intégré au chromosome. L’infection comprend la primo-infection (charge virale élevée, signes grippaux), une phase asymptomatique longue (séropositivité), puis la chute des LT4 et le SIDA avec des maladies opportunistes. Il se transmet par voie sexuelle (80 % des cas), par le sang et de la mère à l’enfant.",
  ["Allergie : IgE, mastocytes, histamine.", "Auto-immunité : destruction du soi.", "Déficits congénitaux et acquis.", "VIH : cible les LT4 (CD4).", "Phases : primo-infection, asymptomatique, SIDA."],
  ("Pourquoi la destruction des LT4 par le VIH affaiblit-elle à la fois la RIMH et la RIMC ?", "Les LT4 sécrètent l’interleukine 2 qui active la multiplication des LB et des LT8 : sans eux, les deux réponses s’effondrent."),
  [S("Dysfonctionnements", table=[["Type", "Exemple", "Mécanisme"], ["Hyperfonctionnement", "allergie", "IgE, histamine des mastocytes"], ["Auto-immunité", "diabète insulino-dépendant", "destruction des cellules β"], ["Déficit congénital", "enfants « bulles »", "absence de lignées immunitaires"], ["Déficit acquis", "SIDA", "destruction des LT4 par le VIH"]]),
   S("Évolution de l’infection par le VIH", ["Primo-infection : charge virale ↑, anticorps anti-VIH apparaissent.", "Phase asymptomatique : séropositivité, LT4 diminuent lentement.", "SIDA : LT4 très bas, maladies opportunistes."])],
  apps=[("Quelle protéine des LT4 le VIH reconnaît-il ?", "La protéine CD4, grâce à sa protéine d’enveloppe gp120."), ("Citer trois modes de transmission du VIH.", "Rapports sexuels, sang contaminé (seringues, objets tranchants), de la mère à l’enfant.")]),
L("Chapitre VI : Aides au système immunitaire", [314, 318],
  ["Comparer vaccination et sérothérapie.", "Citer les types de greffes et les conditions de leur réussite.", "Citer d’autres traitements (immunosuppresseurs, immunomodulateurs, trithérapie)."],
  "Pourquoi injecte-t-on un sérum, et non un vaccin, à un blessé non vacciné contre le tétanos ?",
  "La vaccination injecte un antigène rendu inoffensif (anatoxine, microbe atténué ou tué) : elle déclenche une réponse primaire et la formation de cellules mémoires ; c’est une immunité active, lente à s’installer mais durable ; les rappels entretiennent la mémoire. La sérothérapie injecte des anticorps tout faits (sérum d’origine animale, peu coûteux mais antigénique, ou d’origine humaine, mieux toléré) : c’est une immunité passive, immédiate mais de courte durée, utilisée en urgence (tétanos, rage, venin de serpent) ou en prévention (rubéole chez la femme enceinte, anti-Rh). La sérovaccination associe les deux. Les greffes : autogreffe (même individu) et isogreffe (même génotype) sont acceptées ; allogreffe (génotypes différents) et xénogreffe (espèces différentes) sont rejetées. La réussite exige la meilleure histocompatibilité (antigènes du CMH proches) et un traitement immunosuppresseur (la ciclosporine inhibe l’activité des LTc), qui augmente le risque d’infections. La greffe de moelle osseuse traite certains déficits ; la greffe du thymus traite l’aplasie thymique. Les immunomodulateurs (interleukines) stimulent les défenses. Contre le VIH, les antirétroviraux associés en trithérapie ralentissent la maladie sans éliminer le virus. La chimiothérapie anticancéreuse peut affaiblir l’immunité.",
  ["Vaccination : active, lente, durable, mémoire.", "Sérothérapie : passive, immédiate, brève.", "Autogreffe, isogreffe acceptées ; allogreffe, xénogreffe rejetées.", "Histocompatibilité + immunosuppresseurs.", "Trithérapie contre le VIH."],
  ("Un blessé non vacciné reçoit sérum et vaccin antitétaniques. Pourquoi les deux ?", "Le sérum le protège immédiatement ; le vaccin installe une protection durable avant que les anticorps du sérum disparaissent."),
  [S("Vaccination et sérothérapie", table=[["", "Vaccination", "Sérothérapie"], ["Produit injecté", "antigène inoffensif", "anticorps"], ["Immunité", "active", "passive"], ["Délai", "quelques semaines", "immédiat"], ["Durée", "longue (mémoire)", "courte"], ["Usage", "prévention", "urgence"]]),
   S("Types de greffes", table=[["Greffe", "Donneur", "Résultat"], ["Autogreffe", "le même individu", "acceptée"], ["Isogreffe", "même génotype (vrais jumeaux)", "acceptée"], ["Allogreffe", "même espèce, génotype différent", "rejetée sans traitement"], ["Xénogreffe", "autre espèce", "rejetée"]])],
  apps=[("Pourquoi un sérum d’origine animale peut-il provoquer une réaction allergique ?", "Ses anticorps sont eux-mêmes des antigènes pour le receveur."), ("Quelles greffes ont le meilleur taux de réussite ?", "Les autogreffes et les isogreffes.")]),
]

